 12→type CreditType = { key: string; color: string; label: string; count: number; desc: string };
 13→
 14→const CREDIT_TYPES: Omit<CreditType, "count">[] = [
 15→  { key: "monthly", color: "hsl(var(--primary))", label: "Monthly", desc: "From your subscription — consumed first." },
 16→  { key: "topup", color: "hsl(var(--score-overall))", label: "Top-up", desc: "One-time pack purchase — never expire, used after monthly." },
 17→  { key: "bonus", color: "hsl(var(--score-education))", label: "Bonus", desc: "Bonus credits — used last, never expire." },
 18→];
 19→
 20→const AccountInfoCard = () => {
 21→  const { user, profile } = useAuth();
 22→  const navigate = useNavigate();
 23→  const [animated, setAnimated] = useState(false);
 24→
 25→  useEffect(() => {
 26→    const t = setTimeout(() => setAnimated(true), 50);
 27→    return () => clearTimeout(t);
 28→  }, []);
 29→
 30→  const subCredits = profile?.subscription_credits ?? 0;
 31→  const topCredits = profile?.topup_credits ?? 0;
 32→  const bonusCredits = profile?.bonus_credits ?? 0;
 33→  const splitTotal = subCredits + topCredits + bonusCredits;
 34→  const legacyCredits = profile?.credits ?? 0;
 35→  const total = splitTotal > 0 ? splitTotal : legacyCredits;
 36→  const showLegacy = splitTotal === 0 && legacyCredits > 0;
 37→
 38→  const plan = profile?.plan ?? "free";
 39→  const isPaid = plan !== "free";
 40→  const isLow = total < 3;
 41→
 42→  // Build credit types with counts
