  1→import { useState, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Badge } from "@/components/ui/badge";
  7→import { Skeleton } from "@/components/ui/skeleton";
  8→import { Coins, History, Zap } from "lucide-react";
  9→
 10→interface UsageLog {
 11→  id: string;
 12→  created_at: string;
 13→  credits_used: number;
 14→  job_id: string | null;
 15→  job_title?: string | null;
 16→}
 17→
 18→const PAGE_SIZE = 10;
 19→
 20→const UsageHistoryCard = () => {
 21→  const { user } = useAuth();
 22→  const [usageLogs, setUsageLogs] = useState<UsageLog[]>([]);
 23→  const [loading, setLoading] = useState(true);
 24→  const [page, setPage] = useState(0);
 25→  const [hasMore, setHasMore] = useState(false);
 26→  const [loadingMore, setLoadingMore] = useState(false);
 27→
 28→  const fetchLogs = async (pageNum: number, append = false) => {
 29→    if (!user) return;
 30→    if (pageNum === 0) setLoading(true);
 31→    else setLoadingMore(true);
 32→
 33→    const { data } = await supabase
 34→      .from("usage_logs")
 35→      .select("id, created_at, credits_used, job_id")
 36→      .eq("user_id", user.id)
 37→      .order("created_at", { ascending: false })
 38→      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);
 39→
 40→    if (data) {
 41→      setHasMore(data.length === PAGE_SIZE);
 42→      const jobIds = [...new Set(data.map(l => l.job_id).filter(Boolean))] as string[];
 43→      let jobTitles: Record<string, string | null> = {};
 44→      if (jobIds.length > 0) {
 45→        const { data: jobs } = await supabase.from("jobs").select("id, title").in("id", jobIds);
 46→        if (jobs) jobs.forEach(j => { jobTitles[j.id] = j.title; });
 47→      }
 48→      const mapped = data.map(l => ({
 49→        ...l,
 50→        job_title: l.job_id ? (jobTitles[l.job_id] ?? "Untitled Job") : null,
 51→      }));
 52→      setUsageLogs(prev => append ? [...prev, ...mapped] : mapped);
 53→    }
 54→    setLoading(false);
 55→    setLoadingMore(false);
 56→  };
 57→
 58→  useEffect(() => {
 59→    fetchLogs(0);
 60→  }, [user]);
 61→
 62→  const loadMore = () => {
 63→    const nextPage = page + 1;
 64→    setPage(nextPage);
 65→    fetchLogs(nextPage, true);
 66→  };
 67→
 68→  return (
 69→    <Card className="overflow-hidden">
 70→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 71→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 72→          <History className="h-4.5 w-4.5 text-primary" />
 73→        </div>
 74→        <div>
 75→          <h3 className="text-base font-semibold text-foreground">Usage History</h3>
 76→          <p className="text-xs text-muted-foreground">Your credit deductions.</p>
 77→        </div>
 78→      </div>
 79→      <CardContent className="px-6 pt-3 pb-5">
 80→        {loading ? (
 81→          <div className="space-y-3">
 82→            {[...Array(4)].map((_, i) => (
 83→              <Skeleton key={i} className="h-12 w-full rounded-lg" />
 84→            ))}
 85→          </div>
 86→        ) : usageLogs.length === 0 ? (
 87→          <div className="text-center py-10">
 88→            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
 89→              <Zap className="h-6 w-6 text-muted-foreground/40" />
 90→            </div>
 91→            <p className="text-sm text-muted-foreground">
 92→              No credit usage yet. Start ranking resumes to see your history here.
 93→            </p>
 94→          </div>
 95→        ) : (
 96→          <div className="space-y-1">
 97→            {usageLogs.map((log) => (
 98→              <div
 99→                key={log.id}
100→                className="flex items-center justify-between rounded-lg px-3 py-2.5 hover:bg-accent/50 transition-colors"
101→              >
102→                <div className="min-w-0">
103→                  <p className="text-sm font-medium text-foreground truncate">
104→                    {log.job_title ?? "No job linked"}
105→                  </p>
106→                  <p className="text-xs text-muted-foreground">
107→                    {new Date(log.created_at).toLocaleDateString("en-US", {
108→                      month: "short", day: "numeric", year: "numeric",
109→                      hour: "2-digit", minute: "2-digit"
110→                    })}
111→                  </p>
112→                </div>
113→                <Badge variant="secondary" className="gap-1 shrink-0 tabular-nums">
114→                  <Coins className="h-3 w-3" />
115→                  -{log.credits_used}
116→                </Badge>
117→              </div>
118→            ))}
119→          </div>
120→        )}
121→        {!loading && usageLogs.length > 0 && hasMore && (
122→          <div className="pt-3 text-center">
123→            <Button variant="outline" size="sm" onClick={loadMore} disabled={loadingMore}>
124→              {loadingMore ? "Loading…" : "Load more"}
125→            </Button>
126→          </div>
127→        )}
128→      </CardContent>
129→    </Card>
130→  );
131→};
132→
133→export default UsageHistoryCard;
