113→/**
114→ * Fetch attachments from Resend API (inbound webhooks only include metadata).
115→ */
116→async function fetchResendAttachments(
117→  resendApiKey: string,
118→  emailId: string,
119→  maxFileSizeBytes: number,
120→): Promise<{ filename: string; content: Uint8Array }[]> {
121→  const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
122→
123→  const listRes = await fetch(
124→    `https://api.resend.com/emails/receiving/${emailId}/attachments`,
125→    { headers: { Authorization: `Bearer ${resendApiKey}` } }
126→  );
127→
128→  if (!listRes.ok) {
129→    console.error("Failed to list Resend attachments:", listRes.status, await listRes.text());
130→    return attachmentFiles;
131→  }
132→
133→  const listData = await listRes.json();
134→  const attachments = listData.data || listData || [];
135→  let count = 0;
136→
137→  for (const att of (Array.isArray(attachments) ? attachments : [])) {
138→    if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
139→    if (!att.filename || !hasAllowedExtension(att.filename)) continue;
140→    if (att.size && att.size > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
141→
142→    try {
143→      const downloadRes = await fetch(att.download_url);
144→      if (!downloadRes.ok) continue;
145→      const buffer = await downloadRes.arrayBuffer();
146→      if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
147→      attachmentFiles.push({ filename: att.filename, content: new Uint8Array(buffer) });
148→      count++;
149→    } catch (e) {
150→      console.error(`Failed to download Resend attachment ${att.filename}:`, e);
151→    }
152→  }
153→
154→  return attachmentFiles;
155→}
