157→serve(async (req) => {
158→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
159→
160→  // Only accept POST
161→  if (req.method !== "POST") {
162→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
163→      status: 405,
164→      headers: { ...corsHeaders, "Content-Type": "application/json" },
165→    });
166→  }
167→
168→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
169→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
170→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
171→
172→  // Helper to log and respond
173→  const logAndRespond = async (
174→    status: number,
175→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
176→    responseBody: Record<string, unknown>
177→  ) => {
178→    try {
179→      await supabase.from("email_ingest_logs").insert({
180→        sender: logData.sender || null,
181→        recipient: logData.recipient || null,
182→        user_id: logData.user_id || null,
183→        job_id: logData.job_id || null,
184→        status: logData.status,
185→        error_message: logData.error_message || null,
186→        attachments_count: logData.attachments_count || 0,
187→        resumes_created: logData.resumes_created || 0,
188→      });
189→    } catch (e) {
190→      console.error("Failed to log email ingest:", e);
191→      await logSystemError({
192→        function_name: "email-ingest",
193→        error_type: "INGEST_LOG_ERROR",
194→        severity: "warning",
195→        error_message: errorToMessage(e),
196→        error_stack: errorToStack(e),
197→        user_id: logData.user_id || null,
198→        job_id: logData.job_id || null,
199→      });
200→    }
201→    return new Response(JSON.stringify(responseBody), {
202→      status,
203→      headers: { ...corsHeaders, "Content-Type": "application/json" },
204→    });
205→  };
206→
207→  try {
208→    // Load platform config first — needed for webhook secret and settings
209→    const { data: config } = await supabase
210→      .from("platform_config")
211→      .select("email_ingestion_enabled, max_file_size_mb, max_resumes_per_job, resend_api_key, resend_inbound_webhook_secret")
212→      .limit(1)
213→      .single();
214→
215→    // --- [C1 FIX] Verify webhook signature before processing ---
216→    // Support both Svix (Resend) and HMAC verification
217→    const rawBodyText = await req.clone().text();
218→    const rawBody = new TextEncoder().encode(rawBodyText).buffer;
219→
220→    const hasSvixHeaders = req.headers.has("svix-id") && req.headers.has("svix-signature");
221→    let isValid = false;
222→
223→    if (hasSvixHeaders) {
224→      // Try DB-stored secret first, fallback to env var
225→      const svixSecret = (config as any)?.resend_inbound_webhook_secret || Deno.env.get("RESEND_INBOUND_WEBHOOK_SECRET");
226→      if (svixSecret) {
227→        isValid = verifySvixSignature(req, rawBodyText, svixSecret);
228→      }
229→    }
230→    if (!isValid) {
231→      isValid = await verifyWebhookSignature(req, rawBody);
232→    }
233→
234→    if (!isValid) {
235→      return await logAndRespond(
236→        401,
237→        { status: "rejected", error_message: "Invalid or missing webhook signature" },
238→        { error: "Unauthorized" }
239→      );
240→    }
241→
242→    // Check global email ingestion toggle
243→    if (config && !config.email_ingestion_enabled) {
244→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
245→    }
246→
247→    const maxFileSizeBytes = (config?.max_file_size_mb || 10) * 1024 * 1024;
248→    const maxResumesPerJob = config?.max_resumes_per_job || 50;
249→
250→    // Parse incoming payload — support structured JSON and multipart/form-data
251→    let sender: string | null = null;
252→    let recipient: string | null = null;
253→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
254→
255→    const contentType = req.headers.get("content-type") || "";
256→
257→    if (contentType.includes("application/json")) {
258→      const body = await req.json();
259→
260→      // Resend inbound webhook format (email.received event)
